import React from 'react';

import clsx from 'clsx';

import { round } from '@helpers/mathHelper';

import style from './style.module.less';
import { IBaseFoodAct } from '../../../../../@types/hiking.baseTypes';
import { IHiker } from '../../../../../@types/hiking.types';
import {
  IHikingMenuAssigneeUser,
  IHikingMenuExtendedProduct,
} from '../../../../../@types/hikingMenu.types';

interface IProductForPrintUse {
  d1: Date;
  d2: Date;
  amount: number;
  act: IBaseFoodAct;
  hikersForAct: IHiker[];
  assigneeUser: IHikingMenuAssigneeUser | null;
}

export interface IProductForPrint extends IHikingMenuExtendedProduct {
  use: IProductForPrintUse[];
  firstDate: Date;
}

interface IProductsPrintModalProps {
  productsForPrint: Record<number, IProductForPrint>;
  dateFrom?: Date;
  dateTo?: Date;
  isIncludeForce?: boolean;
  isIncludeAssignee?: boolean;
}

const ProductsMatrix: React.FC<IProductsPrintModalProps> = ({
  productsForPrint,
  isIncludeForce = true,
  isIncludeAssignee = false,
  dateFrom,
  dateTo,
}) => {
  interface IDateActs extends IProductForPrintUse {
    amount: number;
  }

  const dateActs: Record<string, Record<number, IDateActs>> = {};
  const productsDateActs: Record<string, Record<string, Record<number, number>>> = {};
  const productForces: Record<string, IHikingMenuAssigneeUser> = {};

  const date1 = dateFrom ?? '';
  const date2 = dateTo ?? '';
  const excludeForce = !isIncludeForce;
  const needAssignee = isIncludeAssignee;

  Object.values(productsForPrint)
    .filter((p) => !excludeForce || !p.idForce)
    .sort((a, b) => {
      if (a.firstDate < b.firstDate) {
        return -1;
      }
      if (a.firstDate > b.firstDate) {
        return 1;
      }
      return 0;
    })
    .forEach((p) => {
      const paKey = p.name;

      if (p.forcedUser) {
        productForces[p.name] = p.forcedUser;
      }

      if (!productsDateActs[paKey]) {
        productsDateActs[paKey] = {};
      }

      p.use.forEach((u) => {
        if (!Number.isNaN(+date1) && u.d1 < date1) {
          return;
        }

        if (!Number.isNaN(+date2) && u.d1 > date2) {
          return;
        }

        if (!dateActs[u.d1.toLocaleDateString()]) {
          dateActs[u.d1.toLocaleDateString()] = {};
        }
        if (!dateActs[u.d1.toLocaleDateString()][u.act.id]) {
          dateActs[u.d1.toLocaleDateString()][u.act.id] = {
            ...u,
            amount: 0,
          };
        }
        if (!productsDateActs[paKey][u.d1.toLocaleDateString()]) {
          productsDateActs[paKey][u.d1.toLocaleDateString()] = {};
        }
        if (!productsDateActs[paKey][u.d1.toLocaleDateString()][u.act.id]) {
          productsDateActs[paKey][u.d1.toLocaleDateString()][u.act.id] = 0;
        }
        productsDateActs[paKey][u.d1.toLocaleDateString()][u.act.id] +=
          u.amount * u.hikersForAct.length;
        dateActs[u.d1.toLocaleDateString()][u.act.id].amount += u.amount * u.hikersForAct.length;
      });
    });

  const sortedActs = Object.values(dateActs).toSorted((a, b) => {
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    //@ts-ignore
    return Object.values(a)[0].d1 - Object.values(b)[0].d1;
  });

  return (
    <div className={style.container}>
      <table className={style.table}>
        <thead>
          <tr>
            <th rowSpan={2}>Продукт/Дата</th>
            {sortedActs.map((sa) => {
              const acts = Object.values(sa);
              return (
                <th key={acts[0].d1.toLocaleDateString()} colSpan={acts.length}>
                  {acts[0].d1.toLocaleDateString()}
                </th>
              );
            })}
            <th rowSpan={3}>
              Итого
              <br />
              продукт
            </th>
            <th rowSpan={3}>☑</th>
          </tr>
          <tr>
            {sortedActs.map((sa) => {
              const acts = Object.values(sa);
              return acts.map((aa) => {
                const [hh, mm] = aa.d1.toTimeString().substr(0, 5).split(':');
                return (
                  <th key={aa.d1.toISOString()}>
                    {hh}
                    <sup>
                      <small>{mm}</small>
                    </sup>
                  </th>
                );
              });
            })}
          </tr>
          <tr>
            <th>Участников</th>
            {sortedActs.map((sa) => {
              const acts = Object.values(sa);
              return acts.map((aa) => <th key={aa.d1.toString()}>{aa.hikersForAct.length}</th>);
            })}
          </tr>
        </thead>
        <tbody>
          {Object.entries(productsDateActs)
            .filter(([, amounts]) =>
              Object.values(amounts).reduce(
                (acc, val) => acc + Object.values(val).reduce((a, v) => a + v, 0),
                0,
              ),
            )
            .map(([productName, amounts]) => (
              <tr key={productName}>
                <td
                  className={clsx(productForces[productName] && style.ceilBg)}
                  style={{
                    maxWidth: 150,
                    backgroundImage: productForces[productName]
                      ? `url(${productForces[productName].photo})`
                      : '',
                  }}
                >
                  <div className="text-nowrap text-truncate">{productName.substr(0, 23)}</div>
                </td>
                {sortedActs.map((sa) => {
                  const acts = Object.values(sa);
                  return acts.map((aa) => {
                    const txt =
                      amounts[aa.d1.toLocaleDateString()] &&
                      amounts[aa.d1.toLocaleDateString()][aa.act.id] ? (
                        <>{round(amounts[aa.d1.toLocaleDateString()][aa.act.id])}</>
                      ) : null;
                    let photoUrl = null;

                    if (needAssignee && aa.assigneeUser) {
                      photoUrl = aa.assigneeUser.photo;
                    }

                    return (
                      <td
                        key={productName + aa.d1}
                        className={clsx(txt && photoUrl && style.ceilBg)}
                        style={{ backgroundImage: photoUrl && txt ? `url(${photoUrl})` : '' }}
                      >
                        {txt}
                      </td>
                    );
                  });
                })}
                <td title={JSON.stringify(amounts, null, ' ')}>
                  {Object.values(amounts)
                    .reduce((acc, val) => acc + Object.values(val).reduce((a, v) => a + v, 0), 0)
                    .toLocaleString()}
                </td>
                <td>☐</td>
              </tr>
            ))}
        </tbody>
        <tfoot>
          <tr>
            <td>Итого за приём</td>
            {sortedActs.map((sa) => {
              const acts = Object.values(sa);
              return acts.map((aa) => (
                <td key={aa.d1.toString()}>
                  <small>
                    <b>{aa.amount.toLocaleString()}</b>
                  </small>
                </td>
              ));
            })}
            <td rowSpan={2} colSpan={2}>
              <strong>
                {Object.values(sortedActs)
                  .reduce(
                    (acc, val) => acc + Object.values(val).reduce((a, v) => a + v.amount, 0),
                    0,
                  )
                  .toLocaleString()}
              </strong>
            </td>
          </tr>
          <tr>
            <td>Итого за день</td>
            {sortedActs.map((sa) => {
              const acts = Object.values(sa);
              return (
                <td key={acts[0].d1.toLocaleDateString()} colSpan={acts.length}>
                  <small>
                    <b>
                      {Object.values(acts)
                        .reduce((a, v) => a + v.amount, 0)
                        .toLocaleString()}
                    </b>
                  </small>
                </td>
              );
            })}
          </tr>
        </tfoot>
      </table>
      <br />
    </div>
  );
};

export default ProductsMatrix;
